head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFooterData]<br/>Footer Cell 정보를 사용하여 특정 Footer Cell 의 데이터를 설정합니다.",
    "validation" : [
        "Footer Cell 정보를 사용하여 특정 Footer Cell 의 데이터를 설정해야 합니다.",
        "inputType='text' 인 Footer Cell 에만 동작해야 합니다. (text 가 아닌 Footer Cell 은 미동작)",
        "footerId(필수) 파라미터로 데이터를 설정할 Footer Cell 의 인덱스값을 설정할 수 있어야 합니다. (인덱스는 0 부터 시작하며 숨겨진 Footer Cell 도 포함하여 인덱스가 설정됨)",
        "data(필수) 파라미터로 Footer Cell 에 설정할 데이터 값을 설정할 수 있어야 합니다.",
        "동일한 Footer Cell ID 가 존재하는 경우 해당 Footer Cell 의 데이터가 모두 설정되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // Footer Cell 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - 숨겨진 Footer Cell(index 1) 도 인덱스에 포함됨을 보임
    $c.gcm.createLabel('label="Footer Cell 인덱스 0: ft1(text 합계) / 1: ftHidden(text, hidden=true 숨김 셀) / 2: ft3(expression 비-text) / 3: ft4(text footer4) → 인덱스는 숨김 셀 포함하여 부여됨"', '', 'label1');

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody + Footer 1행)
    //  - Footer Cell 은 inputType="text" 중심, 인덱스 1 은 hidden="true" 숨김 셀, 인덱스 2 는 비-text(expression)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setFooterData 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="구분"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="금액"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="수식"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    // index 0 : 일반 text Footer Cell (설정 정상 동작)
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    // index 1 : 숨김 text Footer Cell (hidden=true) → 숨김 셀도 인덱스 포함됨을 확인
    strTarget += '<w2:column width="130" style="" inputType="text" hidden="true" id="ftHidden" value="숨김초기값"></w2:column>';
    // index 2 : inputType="expression" 비-text Footer Cell (setFooterData 미동작 확인용)
    strTarget += '<w2:column width="130" style="" inputType="expression" id="ft3" expression="1000 + 2345"></w2:column>';
    // index 3 : 일반 text Footer Cell (설정 정상 동작)
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_setFooterData_onclick = function () {
    // footerId 는 인덱스(Number) 로 전달 (숨김 Footer Cell 포함하여 인덱스 부여)
    let footerId = Number(par_footerId.getValue());
    // data(필수) 파라미터
    let data = par_data.getValue();

    // setFooterData 호출 : inputType="text" 인 Footer Cell 에만 동작
    target1.setFooterData(footerId, data);

    // 설정 결과 확인 : 동일 footerId 의 getFooterData 로 설정값 조회
    let after = target1.getFooterData(footerId);
    if (typeof after === 'undefined') {
        after = 'undefined';
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setFooterData(" + footerId + ", '" + data + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("[getFooterData(" + footerId + ") 로 설정 결과 확인] " + after);
}
